------------ lifeCycle ------------

function LadderStruggleBattleAbstractCell:CleanProperties()
    self.data = nil
    self.systemName = nil
    self.component = nil
end

function LadderStruggleBattleAbstractCell:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
end

function LadderStruggleBattleAbstractCell:InitComponent()
    if IsNull(self.LB_PlayerHead.Env) then
        self.LB_PlayerHead:Init()
    end
end

--- 更新cell数据
---@param data any
function LadderStruggleBattleAbstractCell:UpdatePlayerInfo(data)
    if isNull(data) then
        return
    end
    -- print("[大乱斗] 挑战按钮", table.dump(data, nil, 5))
    self.data = data
    local rank = checkInt(data.ranking)
    local playerName = data.name
    local avatarId = checkInt(data.avatar)
    local avatarFrameId = checkInt(data.avatarFrame)
    local level = checkInt(data.level)
    local combatValue = data.combatValue

    self.Txt_Rank.text = tostring(rank)
    self.Txt_PlayerLevel.text = level
    self.Txt_PlayerName.text = playerName
    self.Txt_PlayerCombatValue.text = tostring(combatValue)
    self.LB_PlayerHead.Env:FreshAvatarFrame(avatarId, avatarFrameId)

    KTool.SetActive(self.RT_FirstToThird, rank <= 3)
    KTool.SetActive(self.RT_FourthToFinal, rank > 3)
end

function LadderStruggleBattleAbstractCell:AnimateRankChange(newRank, duration)
    DOTween.To(function(value)
        self.Txt_Rank.text = tostring(Mathf.Floor(value))
    end, checkInt(self.data.ranking), newRank, duration)
end

function LadderStruggleBattleAbstractCell:SetRankDiff(diff)
    self.Txt_RankDiff.text = tostring(diff)
end

return LadderStruggleBattleAbstractCell